cat > /workspace/src/parser.ts <<'EOF'
import { ProfilePatch } from './types';

const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_DISTINCT_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();

  const prototype = Object.getPrototypeOf(input);
  if (prototype !== Object.prototype && prototype !== null) invalid();

  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };

  if ('displayName' in input) {
    const value = (input as { displayName?: unknown }).displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) invalid();
      displayName = { kind: 'set', value: trimmed };
    } else {
      invalid();
    }
  }

  if ('tags' in input) {
    const value = (input as { tags?: unknown }).tags;
    if (value === null || (Array.isArray(value) && value.length === 0)) {
      tags = { kind: 'set', value: [] };
    } else if (Array.isArray(value)) {
      const seen = new Set<string>();
      const trimmedTags: string[] = [];
      for (const item of value) {
        if (typeof item !== 'string') invalid();
        const trimmed = item.trim();
        if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) invalid();
        if (seen.has(trimmed)) continue;
        seen.add(trimmed);
        if (seen.size > MAX_DISTINCT_TAGS) invalid();
        trimmedTags.push(trimmed);
      }
      tags = { kind: 'set', value: trimmedTags };
    } else {
      invalid();
    }
  }

  return { displayName, tags };
}
