const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');

const invalid = (fn) => assert.throws(fn, (e) => e instanceof Error && e.message === 'invalid profile');

// valid updates
const s1 = new ProfileService({ displayName: 'before', tags: ['old'] });
assert.deepEqual(s1.patch({ displayName: 'after' }), { displayName: 'after', tags: ['old'] });
assert.deepEqual(s1.patch({ tags: ['new'] }), { displayName: 'after', tags: ['new'] });
assert.deepEqual(s1.patch({}), { displayName: 'after', tags: ['new'] }); // no-op

// clearing
assert.deepEqual(s1.patch({ displayName: null }), { displayName: null, tags: ['new'] });
assert.deepEqual(s1.patch({ tags: null }), { displayName: null, tags: [] });
assert.deepEqual(s1.patch({ tags: [] }), { displayName: null, tags: [] });

// trimming and boundaries
const s2 = new ProfileService({ displayName: null, tags: [] });
assert.deepEqual(s2.patch({ displayName: '  x  ', tags: [' a ', 'b'] }), { displayName: 'x', tags: ['a', 'b'] });
assert.deepEqual(s2.patch({ displayName: 'y'.repeat(40) }), { displayName: 'y'.repeat(40), tags: ['a', 'b'] });
assert.deepEqual(s2.patch({ tags: ['z'.repeat(12)] }), { displayName: 'y'.repeat(40), tags: ['z'.repeat(12)] });
assert.deepEqual(s2.patch({ tags: ['t1', ' t1 ', 't2', 't2', 't3', 't4', 't5'] }), { displayName: 'y'.repeat(40), tags: ['t1', 't2', 't3', 't4', 't5'] });

// invalid: shape of input
invalid(() => s2.patch(null));
invalid(() => s2.patch(undefined));
invalid(() => s2.patch(42));
invalid(() => s2.patch('x'));
invalid(() => s2.patch([]));
invalid(() => s2.patch(Object.assign([], { displayName: 'x' })));
const derived = Object.create({ displayName: 'x' });
invalid(() => s2.patch(derived));
invalid(() => s2.patch(new Map()));

// invalid: unknown key
invalid(() => s2.patch({ extra: 1 }));
invalid(() => s2.patch({ displayName: 'ok', extra: null }));

// invalid: displayName
invalid(() => s2.patch({ displayName: 42 }));
invalid(() => s2.patch({ displayName: true }));
invalid(() => s2.patch({ displayName: '' }));
invalid(() => s2.patch({ displayName: '   ' }));
invalid(() => s2.patch({ displayName: 'y'.repeat(41) }));
invalid(() => s2.patch({ displayName: undefined }));

// invalid: tags
invalid(() => s2.patch({ tags: 42 }));
invalid(() => s2.patch({ tags: 'x' }));
invalid(() => s2.patch({ tags: [1] }));
invalid(() => s2.patch({ tags: [null] }));
invalid(() => s2.patch({ tags: [''] }));
invalid(() => s2.patch({ tags: ['  '] }));
invalid(() => s2.patch({ tags: ['ok', ''] }));
invalid(() => s2.patch({ tags: ['z'.repeat(13)] }));
invalid(() => s2.patch({ tags: ['1', '2', '3', '4', '5', '6'] }));

// storage unchanged on failure
const s3 = new ProfileService({ displayName: 'keep', tags: ['keep'] });
invalid(() => s3.patch({ displayName: 'x'.repeat(41), tags: ['fine'] }));
invalid(() => s3.patch({ tags: ['fine', 1] }));
assert.deepEqual(s3.profile, { displayName: 'keep', tags: ['keep'] });

// input object untouched; caller array not reused for storage
const input = { tags: [' caller '] };
const callerTags = input.tags;
const s4 = new ProfileService({ displayName: null, tags: [] });
const result = s4.patch(input);
assert.deepEqual(input, { tags: [' caller '] });
assert.notEqual(result.tags, callerTags);
assert.deepEqual(result, { displayName: null, tags: ['caller'] });
callerTags.push('mutated');
assert.deepEqual(result.tags, ['caller']);

// null-prototype input is accepted
const np = Object.create(null);
np.displayName = 'np';
assert.deepEqual(new ProfileService({ displayName: null, tags: [] }).patch(np), { displayName: 'np', tags: [] });

console.log('checks/patch.cjs passed');
